import random
from math import sqrt

def generate(seed):
    rng = random.Random(seed)
    N = rng.randint(10, 100)

    root = int(sqrt(N))
    answer = sum(N % d == 0 for d in range(1, root + 1)) * 2
    if root * root == N:
        answer -= 1

    check = sum(
        1
        for a in range(1, N + 1)
        for b in range(1, N + 1)
        if a * b == N
    )

    assert answer == check, f"answer={answer} check={check}"

    problem = f"Let N = {N} be a positive integer. How many distinct pairs of positive integers (a, b) satisfy a * b = N? State only the integer."
    return problem, str(answer)


