import random

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)
    m = rng.randint(2, 10)

    # The maximum number of distinct colors that can appear in the grid such that no two cells sharing a side have the same color and the grid is colored in a checkerboard pattern is given by the formula:
    # max_colors = min(n, m)
    answer = min(n, m)

    # A brute-force check: generate all possible checkerboard patterns of size n by n with m colors and count the number of distinct colors that can appear without violating the condition.
    # This is computationally expensive, so we use a simplified approach by generating random checkerboard patterns and checking the distinct colors.
    check = 0
    for _ in range(1000):  # Perform a large number of trials to approximate the maximum
        grid = [[rng.randint(1, m) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i % 2 == 0:
                    if j % 2 == 0:
                        grid[i][j] = grid[i][j - 1]
                    else:
                        grid[i][j] = grid[i - 1][j]
                else:
                    if j % 2 == 0:
                        grid[i][j] = grid[i - 1][j]
                    else:
                        grid[i][j] = grid[i][j - 1]
        colors = set()
        for i in range(n):
            for j in range(n):
                colors.add(grid[i][j])
        if len(colors) == min(n, m):
            check = min(n, m)
            break

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a grid of size {n} by {n}, where each cell can be colored with one of {m} colors. Find the maximum number of distinct colors that can appear in the grid such that no two cells sharing a side have the same color and the grid is colored in a checkerboard pattern. State only the integer."
    )

    return problem, str(answer)


